<?php
require '../config.php'; require_admin(); verify_csrf();
$tab=$_GET['tab']??'dashboard'; $allowed=['dashboard','products','customers','orders','reports','settings']; if(!in_array($tab,$allowed,true))$tab='dashboard';
if($tab==='products' && $_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['save_product'])){ $id=(int)($_POST['id']??0); $name=trim($_POST['name']??'');$price=max(0,(float)($_POST['price']??0));$stock=max(0,(int)($_POST['stock']??0));$cat=(int)($_POST['category_id']??0) ?: null; if($name!==''){if($id){$q=$pdo->prepare('UPDATE products SET name=?,price=?,stock=?,category_id=? WHERE id=?');$q->execute([$name,$price,$stock,$cat,$id]);}else{$q=$pdo->prepare('INSERT INTO products(name,price,stock,category_id) VALUES(?,?,?,?)');$q->execute([$name,$price,$stock,$cat]);}} header('Location: index.php?tab=products');exit;}
if($tab==='products' && isset($_GET['delete'])){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: index.php?tab=products');exit;}
$stats=['products'=>(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'customers'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),'orders'=>(int)$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'sales'=>(float)$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status<>'Cancelled'")->fetchColumn()];
$products=$tab==='products'?$pdo->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll():[];
$cats=$tab==='products'?$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll():[];
$customers=$tab==='customers'?$pdo->query("SELECT id,name,email,phone,created_at FROM users WHERE role='customer' ORDER BY id DESC")->fetchAll():[];
$orders=in_array($tab,['orders','reports'])?$pdo->query('SELECT * FROM orders ORDER BY id DESC LIMIT 100')->fetchAll():[];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin · Mahavir Provision Store</title><link rel="stylesheet" href="../assets/css/store-theme.css"></head><body><div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">🛒</div><div class="brand-copy"><strong>Mahavir Store</strong><small>ADMIN CONSOLE</small></div></div><div class="nav-label">WORKSPACE</div><?php foreach(['dashboard'=>'▦|Dashboard','products'=>'▣|Products','customers'=>'♙|Customers','orders'=>'▤|Orders','reports'=>'▥|Reports','settings'=>'⚙|Settings'] as $key=>$v):[$ic,$label]=explode('|',$v);?><a class="nav-link <?=$tab===$key?'active':''?>" href="?tab=<?=$key?>"><span class="nav-icon"><?=$ic?></span><span class="nav-text"><?=$label?></span></a><?php endforeach; ?><div class="nav-label">STORE</div><a class="nav-link" href="../index.php"><span class="nav-icon">↗</span><span class="nav-text">View website</span></a><a class="nav-link" href="../logout.php"><span class="nav-icon">⇥</span><span class="nav-text">Logout</span></a></aside><main class="main"><header class="topbar"><div><div class="eyebrow">MAHAVIR PROVISION STORE / ADMIN</div><h1 class="page-title"><?=ucfirst($tab)?></h1></div><div class="profile"><div class="avatar">A</div><div class="profile-copy"><b><?=e(current_user()['name'])?></b><small>Administrator</small></div></div></header>
<?php if($tab==='dashboard'):?><section class="welcome"><h2>Welcome, <?=e(current_user()['name'])?> ✨</h2><p>Your store overview at a glance. Manage products, customers and orders from one place.</p><span class="welcome-tag">✦ Galaxy Glass Admin Workspace</span></section><section class="stats"><?php foreach([['▣','Total products',$stats['products'],'Inventory items'],['♙','Customers',$stats['customers'],'Registered accounts'],['▤','Total orders',$stats['orders'],'All-time orders'],['₹','Sales value','₹'.number_format($stats['sales'],2),'Non-cancelled orders']] as $s):?><article class="stat"><div class="stat-head"><span class="muted"><?=$s[1]?></span><span class="stat-icon"><?=$s[0]?></span></div><div class="stat-value"><?=e($s[2])?></div><div class="stat-foot"><?=$s[3]?></div></article><?php endforeach;?></section><section class="panel"><div class="panel-head"><h2 class="panel-title">Quick actions</h2></div><div class="quick-actions"><a class="primary-btn" href="?tab=products">Manage products</a> <a class="primary-btn" href="?tab=orders">View orders</a> <a class="primary-btn" href="?tab=reports">Open reports</a></div></section>
<?php elseif($tab==='products'):?><section class="panel"><div class="panel-head"><h2 class="panel-title">Add a product</h2></div><form method="post" class="product-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="save_product" value="1"><input name="name" placeholder="Product name" required><input name="price" type="number" step=".01" min="0" placeholder="Price ₹" required><input name="stock" type="number" min="0" placeholder="Stock" required><select name="category_id"><option value="">Category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><button class="primary-btn">Save product</button></form></section><section class="panel" style="margin-top:18px"><div class="panel-head"><h2 class="panel-title">Product inventory</h2><span class="muted"><?=count($products)?> items</span></div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>CATEGORY</th><th>PRICE</th><th>STOCK</th><th>ACTION</th></tr></thead><tbody><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category']??'—')?></td><td>₹<?=number_format((float)$p['price'],2)?></td><td><?=e($p['stock'])?></td><td><a class="pill-link" href="?tab=products&delete=<?=$p['id']?>" onclick="return confirm('Delete this product?')">Delete</a></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($tab==='customers'):?><section class="panel"><div class="panel-head"><h2 class="panel-title">Customer directory</h2><span class="muted"><?=count($customers)?> customers</span></div><div class="table-wrap"><table><thead><tr><th>NAME</th><th>EMAIL</th><th>PHONE</th><th>JOINED</th></tr></thead><tbody><?php foreach($customers as $c):?><tr><td><?=e($c['name'])?></td><td><?=e($c['email'])?></td><td><?=e($c['phone'])?></td><td><?=e($c['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($tab==='orders'||$tab==='reports'):?><section class="stats"><article class="stat"><div class="stat-label">Total orders</div><div class="stat-value"><?=$stats['orders']?></div></article><article class="stat"><div class="stat-label">Total sales</div><div class="stat-value">₹<?=number_format($stats['sales'],2)?></div></article></section><section class="panel"><div class="panel-head"><h2 class="panel-title">Recent orders</h2></div><div class="table-wrap"><table><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>PHONE</th><th>TOTAL</th><th>STATUS</th><th>DATE</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['customer_name'])?></td><td><?=e($o['phone'])?></td><td>₹<?=number_format((float)$o['total'],2)?></td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else:?><section class="panel"><h2 class="panel-title">Store settings</h2><p class="muted">Store name: Mahavir Provision Store</p><p class="muted">Currency: INR (₹)</p><p class="muted">For production, configure HTTPS, strong admin credentials, backups and database access restrictions.</p></section><?php endif;?></main></div></body></html>
